/* Atelier Montres — source-backed discovery, no unauthorized product photos.
   The artwork is deliberately typographic, never an exact-model rendering. */
.am-picks{background:#f1f0e9;padding:clamp(54px,6vw,88px) 0;border-top:1px solid #dbddcf;border-bottom:1px solid #d5dacd}
.am-picks-heading{max-width:920px;margin-bottom:26px}
.am-picks-heading .overline{color:#846336}
.am-picks-heading h2,.am-picks-intro h1{color:#203a2b;font:400 clamp(31px,4.8vw,54px)/1.16 Georgia,serif;letter-spacing:-.032em;margin:11px 0 16px}
.am-picks-heading>p:last-child,.am-picks-intro>p{max-width:850px;color:#435949;font:400 16px/1.75 system-ui,sans-serif}
.am-picks-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:stretch}
.am-pick-card{min-width:0;display:flex;flex-direction:column;border:1px solid #d7d8ce;border-radius:8px;overflow:hidden;background:#fffdf9;box-shadow:0 15px 38px #203b2910;isolation:isolate}
.am-pick-visual{--visual-bg:#173c32;--visual-light:#d9d6bc;--visual-ornament:#c3a978;position:relative;isolation:isolate;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;gap:8px;overflow:hidden;aspect-ratio:1.35/1;min-height:175px;padding:22px;color:#fff;background:radial-gradient(ellipse at 76% 34%,#4c6551 0%,var(--visual-bg) 70%)}
.am-pick-retro .am-pick-visual{--visual-bg:#354a52;--visual-light:#f2e5bc;--visual-ornament:#d0cfca}
.am-pick-compact .am-pick-visual{--visual-bg:#674558;--visual-light:#f4dae0;--visual-ornament:#e2a6bd}
.am-pick-dress .am-pick-visual{--visual-bg:#504838;--visual-light:#f8e9b6;--visual-ornament:#e4d4a7}
.am-pick-steel .am-pick-visual{--visual-bg:#2d4555;--visual-light:#dce7f0;--visual-ornament:#b5d1d5}
.am-pick-visual::before{content:'';position:absolute;top:16%;right:6%;width:145px;max-width:48%;aspect-ratio:1;border:9px solid var(--visual-ornament);border-radius:50%;opacity:.16;transform:rotate(-25deg);box-shadow:0 0 0 18px #ffffff20,0 0 0 31px #ffffff13;pointer-events:none;z-index:-1}
.am-pick-visual-top{align-self:flex-start;border:1px solid #ffffff7a;border-radius:99px;padding:5px 10px;color:#fff7ed;font:750 11px/1.5 system-ui,sans-serif}
.am-pick-visual-name{margin-top:auto;color:var(--visual-light);font:750 13px/1.35 system-ui,sans-serif;letter-spacing:.11em;text-transform:uppercase;overflow-wrap:anywhere}
.am-pick-visual-ref{color:#fff;font:400 clamp(24px,2.4vw,34px)/1.17 Georgia,serif;letter-spacing:-.015em;overflow-wrap:anywhere}
.am-pick-visual-caption{color:#ede9df;font:400 11px/1.5 system-ui,sans-serif;opacity:.9}
.am-pick-content{padding:22px;display:flex;flex:1;flex-direction:column;align-items:stretch;gap:11px}
.am-pick-kicker{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:7px;margin:0;color:#6b5536;font:750 11px/1.4 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.035em}
.am-pick-kicker span:last-child{background:#eff2ea;color:#355744;border-radius:3px;padding:5px 8px}
.am-pick-content h3{color:#243f2d;font:400 clamp(22px,2.5vw,29px)/1.25 Georgia,serif;margin:0;overflow-wrap:anywhere}
.am-pick-lead{font:400 14px/1.7 system-ui,sans-serif;color:#3f5645;margin:0}
.am-pick-specs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:3px 0 0}
.am-pick-specs div{min-width:0;border-top:1px solid #d8d9cf;padding-top:8px}
.am-pick-specs dt{color:#627568;font:600 12px/1.45 system-ui,sans-serif;margin:0 0 4px}
.am-pick-specs dd{margin:0;color:#223c2e;font:700 13px/1.5 system-ui,sans-serif;overflow-wrap:anywhere}
.am-pick-caution{font:400 13px/1.65 system-ui,sans-serif;color:#526454;margin:0}
.am-pick-actions{display:grid;gap:8px;margin-top:auto;padding-top:8px}
.am-pick-actions a{display:flex;align-items:center;justify-content:center;min-width:0;min-height:47px;padding:11px 12px;border:1px solid #244b36;border-radius:4px;background:#234835;color:#fff;text-align:center;text-decoration:none;font:700 13px/1.45 system-ui,sans-serif;overflow-wrap:anywhere}
.am-pick-actions a:hover{background:#38634d;color:#fff}
.am-pick-actions a:last-child:not(:first-child){background:transparent;color:#264936;border-color:#b4c2b4}
.am-pick-actions a:last-child:not(:first-child):hover{background:#edf2e9}
.am-pick-actions a:focus-visible,.am-picks-more:focus-visible,.am-picks-tier-nav a:focus-visible,.am-pick-source a:focus-visible{outline:3px solid #b9852b;outline-offset:3px}
.am-pick-source{color:#526557;font:400 12px/1.65 system-ui,sans-serif;margin:0}
.am-pick-source a{color:#2d6144;text-decoration:underline;text-underline-offset:3px}
.am-pick-note{color:#607264;font:400 12px/1.65 system-ui,sans-serif;margin:0}
.am-picks-disclaimer{max-width:1100px;color:#56695a;font:400 13px/1.8 system-ui,sans-serif;margin:21px 0 15px}
.am-picks-more{display:inline-flex;align-items:center;min-height:48px;padding:13px 19px;margin-top:7px;border:1px solid #244b35;border-radius:4px;color:#fff;background:#244b35;text-decoration:none;font:700 14px/1.45 system-ui,sans-serif}
.am-picks-more:hover{background:#315d45;color:#fff}
.am-picks-page{padding-block:30px 85px}
.am-picks-intro{max-width:1020px;margin:25px 0 43px}
.am-picks-intro h1{max-width:920px}
.am-picks-intro>p{font-size:15px;line-height:1.75}
.am-picks-tier-nav{display:flex;gap:11px;flex-wrap:wrap;margin-top:22px}
.am-picks-tier-nav a{display:inline-flex;align-items:center;min-height:44px;padding:10px 17px;border:1px solid #b7c3b4;border-radius:4px;color:#234734;background:#eff2ea;font:700 14px/1.3 system-ui,sans-serif;text-decoration:none}
.am-picks-tier{padding:25px 0 35px}
.am-picks-tier h2{font:400 clamp(30px,4vw,43px)/1.2 Georgia,serif;color:#24412e;margin:0 0 20px}
.am-picks-method{margin-top:35px;padding:25px 27px;border-left:4px solid #b49a65;background:#f0efe6;color:#455b49}
.am-picks-method h2{font:400 30px/1.25 Georgia,serif;color:#203b2b;margin:0 0 13px}
.am-picks-method p{font:400 14px/1.85 system-ui,sans-serif;max-width:95ch}
.am-picks-method a{color:#235b3b}
@media(max-width:1020px){.am-picks-grid{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:650px){.am-picks-grid{grid-template-columns:1fr}.am-picks{padding:48px 0}.am-pick-visual{aspect-ratio:1.7/1;min-height:180px;padding:18px}.am-pick-content{padding:19px}.am-picks-heading h2{font-size:34px}.am-picks-intro h1{font-size:35px}.am-picks-page{padding-bottom:55px}.am-picks-method{padding:17px 18px}}
@media(prefers-reduced-motion:reduce){.am-pick-card,.am-pick-actions a{transition:none}}


/* Individual model landing pages — editorial luxury, without misrepresenting
   typography as a licensed photograph or presenting invented checkout prices. */
.am-pick-detail-link{color:inherit;text-decoration:none;text-underline-offset:5px}
.am-pick-detail-link:hover{text-decoration:underline;color:#326449}
.am-pick-detail-link:focus-visible{outline:3px solid #b9852b;outline-offset:3px;border-radius:2px}
.am-extra-page{padding-block:32px 85px}
.am-extra-product{margin-top:24px}
.am-extra-hero{display:grid;grid-template-columns:minmax(0,.93fr) minmax(0,1.07fr);gap:clamp(20px,3vw,47px);align-items:stretch}
.am-extra-art{--extra-shade:#173b33;--extra-accent:#cfb783;display:flex;flex-direction:column;justify-content:flex-end;position:relative;isolation:isolate;overflow:hidden;min-width:0;min-height:505px;padding:clamp(24px,3.3vw,43px);color:#fff;background:radial-gradient(ellipse at 70% 18%,#5d7c67 0%,var(--extra-shade) 70%);border:1px solid #bdad8a;box-shadow:0 25px 60px #10291b1b}
.am-extra-art.am-pick-retro{--extra-shade:#304451;--extra-accent:#d5e6f3}
.am-extra-art.am-pick-compact{--extra-shade:#614557;--extra-accent:#ffe3ea}
.am-extra-art.am-pick-dress{--extra-shade:#554637;--extra-accent:#f0d09b}
.am-extra-art.am-pick-steel{--extra-shade:#2c485e;--extra-accent:#d1e1e7}
.am-extra-art::before{content:'';position:absolute;z-index:-1;top:13%;right:-10%;width:72%;aspect-ratio:1;border:19px solid var(--extra-accent);border-radius:50%;opacity:.12;box-shadow:0 0 0 24px #ffffff19,0 0 0 52px #ffffff09}
.am-extra-art::after{content:'';position:absolute;z-index:-1;left:16%;top:14%;width:68%;height:1px;background:linear-gradient(90deg,transparent,#ffffff6b,transparent);transform:rotate(-33deg)}
.am-extra-art-kicker{align-self:flex-start;margin-bottom:auto;padding:8px 13px;border:1px solid #ffffff72;border-radius:30px;color:#f8efe3;font:700 12px/1.45 system-ui,sans-serif;letter-spacing:.03em}
.am-extra-art-brand{display:block;color:var(--extra-accent);font:750 15px/1.5 system-ui,sans-serif;letter-spacing:.19em;text-transform:uppercase;overflow-wrap:anywhere}
.am-extra-art-model{display:block;max-width:100%;margin:12px 0 16px;color:#fff;font:400 clamp(38px,4vw,66px)/1.09 Georgia,serif;letter-spacing:-.02em;overflow-wrap:anywhere}
.am-extra-art-label{color:#eee7db;font:400 12px/1.6 system-ui,sans-serif}
.am-extra-intro{display:flex;flex-direction:column;align-items:stretch;justify-content:center;min-width:0}
.am-extra-overline{color:#5a492d;font:750 12px/1.5 system-ui,sans-serif;letter-spacing:.07em;text-transform:uppercase;margin:0 0 11px}
.am-extra-intro h1{font:400 clamp(33px,3.65vw,55px)/1.14 Georgia,serif;letter-spacing:-.03em;overflow-wrap:anywhere;color:#193928;margin:0 0 15px}
.am-extra-subtitle{font:400 clamp(16px,1.8vw,20px)/1.6 system-ui,sans-serif;color:#385a44;margin:0 0 23px}
.am-extra-facts{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:0 17px;margin:0 0 14px;padding:15px 20px;background:#f2f0e8;border:1px solid #ded8ca}
.am-extra-fact{min-width:0;border-bottom:1px solid #d9d4ca;padding:10px 0 13px}
.am-extra-fact dt{font:650 12px/1.5 system-ui,sans-serif;color:#3e5944;margin:0 0 5px}
.am-extra-fact dd{font:700 14px/1.55 system-ui,sans-serif;color:#23442d;margin:0;overflow-wrap:anywhere}
.am-extra-approval{color:#435b4b;font:400 13px/1.75 system-ui,sans-serif;margin:0 0 15px}
.am-extra-actions{display:grid;gap:9px}
.am-extra-actions a{display:flex;align-items:center;justify-content:center;min-height:49px;padding:12px 16px;border-radius:5px;text-decoration:none;text-align:center;overflow-wrap:anywhere;font:750 14px/1.5 system-ui,sans-serif;border:1px solid #25543d;background:#234b35;color:white}
.am-extra-actions a:last-child:not(:first-child){border-color:#9baa95;background:#f9f8f0;color:#234b35}
.am-extra-actions a:hover{filter:brightness(1.12)}
.am-extra-actions a:focus-visible{outline:3px solid #bd8e42;outline-offset:3px}
.am-extra-disclosure{color:#435b4b;font:400 12px/1.7 system-ui,sans-serif;margin:12px 0 0}
.am-extra-merchant-variant{display:block;margin-top:6px;padding-top:8px;border-top:1px solid #b8cfb6;font:500 12px/1.6 system-ui,sans-serif;color:#284b3a;overflow-wrap:anywhere}
.am-extra-merchant-variant strong{font-weight:750}

.am-extra-local-nav{display:flex;gap:10px;overflow-x:auto;scroll-snap-type:x proximity;padding:20px 2px 26px}
.am-extra-local-nav a{flex:0 0 auto;display:inline-flex;align-items:center;min-height:44px;padding:10px 15px;background:#eee9dd;border:1px solid #cfc4ad;color:#284c36;text-decoration:none;font:700 13px/1.4 system-ui,sans-serif;scroll-snap-align:start}
.am-extra-local-nav a:focus-visible{outline:3px solid #b9852b;outline-offset:2px}
.am-extra-page section[id]{scroll-margin-top:25px}
.am-extra-editorial,.am-extra-provenance,.am-extra-related,.am-extra-checks{margin:25px 0 35px}
.am-extra-editorial h2,.am-extra-provenance h2,.am-extra-related h2,.am-extra-checks h2{font:400 clamp(27px,3.6vw,41px)/1.2 Georgia,serif;letter-spacing:-.023em;color:#1c3b2b;margin:0 0 17px}
.am-extra-editorial-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}
.am-extra-editorial-grid>div{padding:22px 24px;border:1px solid #d6dacd;background:#f7f7f1}
.am-extra-index{display:block;font:400 35px/1.2 Georgia,serif;color:#80603b;margin-bottom:10px}
.am-extra-editorial-grid h3{font:400 24px/1.2 Georgia,serif;color:#1d4131;margin:0 0 12px}
.am-extra-editorial-grid p,.am-extra-provenance p,.am-extra-related>p,.am-extra-checks li,.am-extra-checks p{max-width:90ch;color:#435d4d;font:400 15px/1.8 system-ui,sans-serif}
.am-extra-provenance{padding:24px 28px;background:#f2f1e8;border-left:4px solid #bba075}
.am-extra-provenance p{margin:10px 0}
.am-extra-provenance a,.am-extra-related a,.am-extra-return a{color:#215b3c;text-decoration:underline;text-underline-offset:3px}
.am-extra-provenance a:focus-visible,.am-extra-related a:focus-visible,.am-extra-return a:focus-visible{outline:3px solid #b9852b;outline-offset:3px}
.am-extra-related ul{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;list-style:none;padding:0;margin:18px 0}
.am-extra-related li{min-width:0;display:flex;flex-direction:column;gap:9px;background:#fffefa;border:1px solid #d9ded1;padding:18px}
.am-extra-related li a{font:700 15px/1.4 system-ui,sans-serif;overflow-wrap:anywhere}
.am-extra-related li span{font:400 13px/1.65 system-ui,sans-serif;color:#435b4b}

/* Reference-first conversion: do not confuse a search with an exact product. */
.am-extra-reference{display:flex;flex-wrap:wrap;align-items:baseline;gap:6px 12px;margin:0 0 12px;padding:12px 15px;border:1px solid #d4dccc;background:#eef1e8}
.am-extra-reference span{font:650 12px/1.5 system-ui,sans-serif;color:#38563e}
.am-extra-reference strong{font:750 15px/1.5 system-ui,sans-serif;color:#1c3f2a;overflow-wrap:anywhere}
.am-extra-link-status{display:flex;flex-direction:column;gap:5px;margin:0 0 11px;padding:12px 15px;border:1px solid #d5d4c7;border-left:4px solid #8d754e;background:#faf7ef;color:#3c4c3e}
.am-extra-link-status strong{font:750 13px/1.5 system-ui,sans-serif}
.am-extra-link-status span{font:400 12px/1.6 system-ui,sans-serif}
.am-extra-link-direct{border-left-color:#35644b;background:#eff4ec}
.am-extra-related li{padding:11px}
.am-extra-related li .am-extra-related-thumb{display:grid;place-items:center;width:100%;height:160px;margin-bottom:3px;overflow:hidden;background:linear-gradient(145deg,#f7f7f1,#e4ebe2);text-decoration:none;border:1px solid #e1e4d9}
.am-extra-related li .am-extra-related-thumb img{width:100%;height:100%;object-fit:contain;padding:8px}
.am-extra-related li .am-extra-related-fallback{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:6px;width:100%;height:100%;padding:12px;text-align:center;color:#d9eadc;background:linear-gradient(145deg,#436052,#243f35)}
.am-extra-related li .am-extra-related-fallback span{color:#e6e9d9;font:700 11px/1.35 system-ui,sans-serif;letter-spacing:.1em}
.am-extra-related li .am-extra-related-fallback strong{font:500 25px/1.15 Georgia,serif;color:#fff;overflow-wrap:anywhere}
.am-extra-related li .am-extra-related-fallback small{font:450 11px/1.4 system-ui,sans-serif;color:#e1e7dc}
.am-extra-related li .am-extra-related-label{color:#6b532d;font:750 11px/1.45 system-ui,sans-serif;letter-spacing:.08em;text-transform:uppercase}
.am-extra-related li .am-extra-related-name{min-height:42px;display:inline-flex;align-items:center;font:750 15px/1.45 system-ui,sans-serif}
.am-extra-related li .am-extra-related-thumb:focus-visible{outline:3px solid #b9852b;outline-offset:3px}

.am-extra-related>a{display:inline-flex;align-items:center;min-height:44px;font:700 14px/1.45 system-ui,sans-serif}
.am-extra-checks ol{padding-left:24px;max-width:90ch}
.am-extra-checks li{padding-left:5px;margin-bottom:8px}
.am-extra-return{margin-top:35px;font:700 14px/1.5 system-ui,sans-serif}
.am-extra-return a{display:inline-flex;min-height:44px;align-items:center}
@media(max-width:900px){
 .am-extra-hero{grid-template-columns:1fr;gap:19px}
 .am-extra-art{min-height:350px}
 .am-extra-art-model{font-size:clamp(35px,6vw,60px)}
 .am-extra-related ul{grid-template-columns:repeat(2,minmax(0,1fr))}
}
@media(max-width:570px){
 .am-extra-page{padding-block:20px 55px}
 .am-extra-art{min-height:260px;padding:23px}
 .am-extra-art-model{font-size:clamp(31px,8vw,48px)}
 .am-extra-intro h1{font-size:clamp(32px,8vw,42px)}
 .am-extra-subtitle{font-size:16px}
 .am-extra-facts{padding:10px 15px;gap:0 11px}
 .am-extra-editorial-grid,.am-extra-related ul{grid-template-columns:1fr}
 .am-extra-editorial-grid>div{padding:18px 20px}
 .am-extra-provenance{padding:18px 19px}
 .am-extra-local-nav{margin-right:-14px;padding-right:14px}
}
@media(prefers-reduced-motion:reduce){.am-extra-actions a{transition:none}}

/* Client-side discovery is progressive: all cards remain visible without JS. */
.am-pick-filters{margin:0 0 22px;padding:clamp(15px,2.6vw,26px);border:1px solid #c9d5c9;background:#f7f7f1;box-shadow:0 8px 27px #22412e0c;border-radius:7px}
.am-pick-filter-fields{display:grid;grid-template-columns:minmax(190px,1.6fr) repeat(3,minmax(138px,1fr));gap:14px}
.am-pick-filter-field{display:flex;flex-direction:column;gap:8px;min-width:0;color:#264a35;font:700 13px/1.45 system-ui,sans-serif}
.am-pick-filter-field input,.am-pick-filter-field select{width:100%;min-width:0;min-height:48px;padding:11px 12px;background:#fff;color:#183b29;border:1px solid #aabcae;border-radius:4px;font:500 14px/1.5 system-ui,sans-serif}
.am-pick-filter-field input::placeholder{color:#647365;opacity:1}
.am-pick-filter-field input:hover,.am-pick-filter-field select:hover{border-color:#557e5e}
.am-pick-filter-field input:focus-visible,.am-pick-filter-field select:focus-visible,.am-pick-filter-footer button:focus-visible{outline:3px solid #b9852b;outline-offset:3px}
.am-pick-filter-footer{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:10px;padding-top:16px}
.am-pick-filter-footer output{font:750 14px/1.5 system-ui,sans-serif;color:#224631}
.am-pick-filter-footer button{min-height:44px;padding:9px 15px;background:#fff;border:1px solid #65856e;border-radius:4px;color:#225136;font:700 13px/1.5 system-ui,sans-serif;cursor:pointer}
.am-pick-filter-footer button:hover{background:#eaf0e8}
.am-pick-filter-empty{padding:24px;border:1px dashed #8ca58f;border-radius:5px;background:#f5f6ee;color:#244633;font:500 15px/1.7 system-ui,sans-serif}
.am-pick-exact{align-self:flex-start;padding:9px 11px;margin:0;border-left:3px solid #4f7553;background:#eef2e9;color:#264d38;font:700 12px/1.55 system-ui,sans-serif}
.am-pick-direct .am-pick-visual{border-bottom:3px solid #b89c61}
.am-picks-page .am-pick-card[hidden],.am-picks-page .am-picks-tier[hidden],.am-picks-page .am-pick-filters[hidden],.am-picks-page .am-pick-filter-empty[hidden]{display:none!important}
@media(max-width:1040px){.am-pick-filter-fields{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:570px){.am-pick-filter-fields{grid-template-columns:1fr;gap:11px}.am-pick-filters{padding:16px}.am-pick-filter-footer{align-items:stretch}.am-pick-filter-footer button{width:100%}}


/* Original watch silhouettes: decorative editorial illustrations, not SKMEI packshots. */
.am-budget-watch{
  pointer-events:none;position:absolute;z-index:0;right:11%;top:20%;
  display:block;width:clamp(58px,26%,115px);aspect-ratio:.87;
  border:clamp(7px,1vw,12px) solid #cdd7d0;border-radius:19%;
  background:radial-gradient(circle at 30% 20%,#445f65,#091c24 70%);
  box-shadow:inset 0 0 0 3px #586970,0 16px 27px #00182185,0 0 0 3px #cfd7d344;
  transform:rotate(-18deg);opacity:.87
}
.am-budget-watch::before,.am-budget-watch::after{
  content:"";position:absolute;z-index:-1;left:20%;width:60%;height:54%;
  border:3px solid #c4d1c7;background:linear-gradient(90deg,#294247,#667675 50%,#2c4346);
}
.am-budget-watch::before{bottom:98%;border-radius:12px 12px 0 0}
.am-budget-watch::after{top:98%;border-radius:0 0 12px 12px}
.am-budget-dial{position:absolute;inset:15%;display:block;border:2px solid #8eaaa2;border-radius:8px;background:
  linear-gradient(170deg,transparent 44%,#b5dad257 49%,transparent 54%),
  linear-gradient(#0c252b,#1c3940)}
