/* Atelier Montres: premium readability and touch design, 2026-10-31.
   One lightweight, local stylesheet shared across catalogue, advisor and watch pages.
   Preserves exact manufacturer photos and all existing application interactions. */
:root{
  --am-p-paper:#faf8f3;
  --am-p-card:#fffdf9;
  --am-p-deep:#183a2a;
  --am-p-text:#20392a;
  --am-p-muted:#4d6353;
  --am-p-brass:#a98955;
  --am-p-border:#dcd5c8;
  --am-p-focus:#b37b25;
  --am-p-radius:8px;
  --am-p-shadow:0 14px 34px rgba(18,48,32,.085);
}
html{scroll-padding-top:92px}
body{font-size:16px}
a,button,input,select,summary{touch-action:manipulation}
:where(a,button,input,select,summary,[tabindex]):focus-visible{
  outline:3px solid var(--am-p-focus);
  outline-offset:3px;
}
.am-topline{font-size:11px;letter-spacing:.11em}
.am-header .navigation a{font-size:13px;letter-spacing:.065em}
.am-mobile-nav>summary{font-size:13px}
.am-mobile-links a{font-size:14px;letter-spacing:.035em}
.aff-selection{background:var(--am-p-paper)}
.aff-heading>p,.aff-heading p,.aff-disclosure p{
  color:var(--am-p-muted);
  line-height:1.75;
}
.aff-disclosure{border-left:3px solid var(--am-p-brass);background:#f0ede5}
.aff-disclosure strong{color:var(--am-p-text);font-size:14px}
.aff-disclosure p{font-size:14px}
.aff-tools{row-gap:15px}
.aff-tabs button{
  min-height:44px;
  padding:10px 14px;
  font-size:13px;
  line-height:1.35;
  border-radius:4px;
}
.aff-tabs button[aria-pressed="true"]{background:var(--am-p-deep);color:#fff}
.am-sort-wrap{font-size:13px;color:var(--am-p-text);font-weight:650}
.am-sort-wrap select{
  min-height:46px;
  font-size:14px;
  color:var(--am-p-text);
  background-color:var(--am-p-card);
  border-color:var(--am-p-border);
  border-radius:4px;
}
.aff-query input{
  min-height:48px;
  font-size:16px;
  border-radius:4px;
  border-color:var(--am-p-border);
}
.aff-query .am-search-hint,.am-size-note{font-size:13px;line-height:1.65;color:var(--am-p-muted)}
.am-view-toolbar-title{font-size:12px;color:var(--am-p-muted)}
.am-view-options{border-radius:6px}
.am-view-options button{font-size:13px;border-radius:3px}
.am-view-explainer{font-size:13px;color:var(--am-p-muted)}
.aff-grid .aff-card{
  border:1px solid var(--am-p-border);
  border-radius:var(--am-p-radius);
  overflow:hidden;
  background:var(--am-p-card);
  box-shadow:var(--am-p-shadow);
}
.aff-grid .aff-illustration{background:linear-gradient(145deg,#fafaf6,#eef1e9)!important}
.aff-grid .aff-card-brand{
  color:#745e3c;
  font-size:12px;
  line-height:1.45;
  letter-spacing:.075em;
}
.aff-grid .aff-card h3{color:var(--am-p-text);line-height:1.22}
.aff-grid .aff-card-desc{font-size:14px;color:var(--am-p-muted)}
.aff-grid .am-spec-line,.aff-grid .aff-card-foot{font-size:12px;color:var(--am-p-muted)}
.aff-grid .am-card-title{font-size:14px;color:var(--am-p-text)}
.aff-grid .aff-chips span{font-size:12px}
.aff-grid .aff-card-actions a{font-size:13px;line-height:1.4;border-radius:4px}
.aff-grid .aff-card-actions button{min-width:44px;min-height:44px}
.aff-grid .am-card-footer a,.aff-grid .am-card-footer label{font-size:13px;line-height:1.45}
.aff-grid .am-affiliate-note{font-size:12px;line-height:1.6;color:var(--am-p-muted)}
.aff-grid[data-view="gallery"] .aff-card-brand{font-size:12px}
.aff-grid[data-view="gallery"] .aff-card h3{
  font-size:clamp(18px,1.9vw,24px);
  line-height:1.25;
  letter-spacing:-.015em;
}
.aff-grid[data-view="gallery"] .am-gallery-facts span{
