/* Interactive watch detail. */
.am-breadcrumb{font-size:13px}
.detail-brand,.detail-facts-caption{font-size:12px}
.detail-story,.detail-info .detail-story{font-size:16px;line-height:1.75;color:var(--am-p-muted)}
