.advisor-match p,.advisor-compare-next p{font-size:14px;line-height:1.65}
.advisor-card-actions a{font-size:14px;line-height:1.45}
.advisor-knowledge article p{font-size:15px}
/* Search-indexable, independent static product and comparison pages. */
.top .nav nav a{font-size:14px}
.watch-product .intro .lead{font-size:16px}
.watch-photo-caption{font-size:12px;line-height:1.5}
.watch-facts-caption{font-size:12px!important}
.watch-quickfact dt{font-size:13px}
.watch-quickfact dd{font-size:15px}
.watch-product .tags span,.watch-product .disclosure{font-size:13px}
.watch-actions .primary,.watch-actions .secondary{font-size:14px}
