/* A genuine photo-only loupe, never a fabricated extra-angle gallery.
   Positioned over the image stage so mobile image height is kept stable. */
.watch-product .watch-photo .watch-photo-zoom{
  position:absolute;z-index:2;right:clamp(12px,2.1vw,23px);bottom:62px;
  display:inline-flex;align-items:center;justify-content:center;gap:8px;
  box-sizing:border-box;max-width:calc(100% - 24px);min-height:44px;
  padding:10px 15px;border:1px solid #a9997b;border-radius:5px;
  background:#fffcf3f2;box-shadow:0 6px 22px #192f251c;
  color:#234330;font:700 13px/1.45 system-ui,sans-serif;
  text-align:center;text-decoration:none;backdrop-filter:blur(8px);
  transition:background-color .16s ease,color .16s ease,border-color .16s ease;
}
.watch-product .watch-photo .watch-photo-zoom span{font-size:19px;line-height:1}
.watch-product .watch-photo .watch-photo-zoom:hover{
  background:#21432f;border-color:#21432f;color:#fff;
}
.watch-product .watch-photo .watch-photo-zoom:focus-visible{
  outline:3px solid #b88435;outline-offset:3px;
}
@media(max-width:480px){
  .watch-product .watch-photo .watch-photo-zoom{right:11px;bottom:50px;padding:9px 11px}
}
