'use strict';
(() => {
  const $=(x)=>document.getElementById(x);
  const cards=$('studioResults'), status=$('studioStatus'), count=$('studioCount'),summary=$('studioSummary'),copy=$('studioCopy'),copyStatus=$('studioCopyStatus'),empty=$('studioEmpty'),form=$('studioCalc'),unit=$('studioUnitCost'),budget=$('studioBudgetStatus');
  if(!cards||!status||!count||!summary||!copy||!form||!unit||!budget)return;
  let candidates=[],selected=new Set(),active='all';
  const KEY='atelier-sourcing-shortlist-v1';
  try{const saved=JSON.parse(localStorage.getItem(KEY)||'[]');if(Array.isArray(saved))selected=new Set(saved.filter(x=>typeof x==='string'))}catch(_){ }
  const node=(tag,cls,value)=>{const el=document.createElement(tag);if(cls)el.className=cls;if(value!==undefined)el.textContent=value;return el};
  const money=(v,c)=>{try{return new Intl.NumberFormat('fr-FR',{style:'currency',currency:c,maximumFractionDigits:2}).format(v)}catch(_){return String(v)+' '+c}};
  const accepted=new Set(['classic','sport','minimal']);
  const valid=(x)=>x&&x.status==='research_only'&&typeof x.id==='string'&&accepted.has(x.family)&&typeof x.supplier==='string'&&typeof x.model==='string'&&Number.isFinite(x.price?.from)&&Number.isFinite(x.price?.to)&&x.price.to>=x.price.from&&['EUR','USD'].includes(x.price.currency)&&Number.isInteger(x.minimumOrderQuantity)&&x.minimumOrderQuantity>0&&Array.isArray(x.issues)&&x.issues.length>=2&&typeof x.sourceUrl==='string'&&x.sourceUrl.startsWith('https://');
  function render() {
    const visible=candidates.filter(c=>active==='all'||(active==='shortlist'?selected.has(c.id):c.family===active));
    cards.replaceChildren(...visible.map(c=>{
      const box=node('article','studio-card');
      box.append(node('span','studio-card-flag','À vérifier — ne pas commander sans devis'));
      box.append(node('h3','',c.supplier));
      box.append(node('p','studio-model',c.model));
      const price=node('p','studio-price',money(c.price.from,c.price.currency)+' – '+money(c.price.to,c.price.currency));
      price.append(node('small','','Tarifs d’annonce, hors importation et livraison'));
      box.append(price);
      const dl=node('dl');
      for(const [name,value] of [['Commande minimale',c.minimumOrderQuantity+' pièce'+(c.minimumOrderQuantity>1?'s':'')],['Marque propre',c.branding]]) {
        const wrap=node('div');wrap.append(node('dt','',name),node('dd','',value));dl.append(wrap);
      }
      box.append(dl);
      const issues=node('div','studio-issues');issues.append(node('strong','','À obtenir avant validation'));
      const ul=node('ul');
      for(const issue of c.issues.slice(0,5))ul.append(node('li','',issue));
      issues.append(ul);box.append(issues);
      const actions=node('div','studio-card-actions');
      const link=node('a','','Voir la fiche fournisseur');
      link.href=c.sourceUrl;link.target='_blank';link.rel='noopener noreferrer';link.title='Ouvrir l’annonce sur le site du fournisseur';
      const button=node('button','',selected.has(c.id)?'✓ Retirer de la liste':'Ajouter à la shortlist');
      button.type='button';button.setAttribute('aria-pressed',String(selected.has(c.id)));
      button.addEventListener('click',()=>{
        selected.has(c.id)?selected.delete(c.id):selected.add(c.id);
        try{localStorage.setItem(KEY,JSON.stringify([...selected]))}catch(_){}
        copyStatus.textContent='';render();
      });
      actions.append(link,button);box.append(actions);
      return box;
    }));
    empty.hidden=visible.length!==0;
    count.textContent=String(selected.size);
    const chosen=candidates.filter(c=>selected.has(c.id));
    summary.textContent=chosen.length?chosen.map(c=>c.supplier).join(' · '):'Sélectionnez des fournisseurs à consulter.';
    status.textContent=visible.length+' offre'+(visible.length>1?'s':'')+' étudiée'+(visible.length>1?'s':'');
    copy.disabled=chosen.length===0;
    document.querySelectorAll('.studio-filters button').forEach(b=>{const yes=b.dataset.filter===active;b.classList.toggle('selected',yes);b.setAttribute('aria-pressed',String(yes))});
  }
  document.querySelectorAll('.studio-filters button').forEach(b=>b.addEventListener('click',()=>{active=b.dataset.filter;render()}));
  copy.addEventListener('click',async()=>{
    const list=candidates.filter(c=>selected.has(c.id));
    if(!list.length)return;
    const txt='Fournisseurs Atelier Montres — vérifications nécessaires\n'+list.map(c=>'- '+c.supplier+' | '+c.model+' | '+c.sourceUrl).join('\n');
    try{await navigator.clipboard.writeText(txt);copyStatus.textContent='Shortlist copiée.'}catch(_){copyStatus.textContent='Copie impossible sur cet appareil : '+list.map(c=>c.supplier).join(', ')}
  });
  const currency=(x)=>new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR'}).format(x);
  function calculate(){
    const values=Object.fromEntries(new FormData(form).entries());
    const quantity=Number(values.quantity),price=Number(values.unitPrice),shipping=Number(values.freight),taxes=Number(values.taxes),extras=Number(values.extras);
    if(!Number.isSafeInteger(quantity)||quantity<1||quantity>1000||![price,shipping,taxes,extras].every(v=>Number.isFinite(v)&&v>=0&&v<=1e5)){
      unit.textContent='—';budget.textContent='Corrigez les montants et la quantité.';return;
    }
    const total=price*quantity+shipping+taxes+extras;
    const landed=total/quantity;
    unit.textContent=currency(landed);
    budget.textContent=(landed<=20?'Dans l’objectif de 20 €':'Au-dessus de l’objectif de 20 €')+' • Total du lot : '+currency(total)+'. Estimation, non devis.';
  }
  form.addEventListener('input',calculate);calculate();
  fetch('./fournisseurs.json',{cache:'no-store'})
    .then(r=>{if(!r.ok)throw Error('feed');return r.json()})
    .then(data=>{
      if(data?.version!==1||!Array.isArray(data.candidates))throw Error('schema');
      candidates=data.candidates.filter(valid);
      selected=new Set([...selected].filter(id=>candidates.some(c=>c.id===id)));
      render();
    })
    .catch(()=>{status.textContent='Données fournisseurs indisponibles.';empty.hidden=false});
})();

/* One source-backed, indexable catalogue for the 15 reviewed and 37 added watches. */
.ud-page{padding:30px 0 90px}
.ud-heading{margin:30px auto 37px;max-width:1020px}
.ud-heading .eyebrow{display:block;color:#5a3f1d;text-transform:uppercase;font-size:12px;letter-spacing:.13em;font-weight:700}
.ud-heading h1{font:400 clamp(40px,6vw,74px)/1.1 Georgia,serif;letter-spacing:-.045em;color:#203f2b;margin:16px 0}
.ud-heading>p{max-width:930px;color:#435b4a;font:400 16px/1.75 system-ui,sans-serif}
.ud-heading .ud-disclosure{font-size:13px;background:#f1f1e8;border-left:4px solid #a68c61;padding:14px 17px}
.ud-filters[hidden],.ud-select[hidden],.ud-compare #udCompareClear[hidden],#udCompareTable[hidden]{display:none!important}
.ud-filters{display:grid;grid-template-columns:minmax(180px,2fr) repeat(5,minmax(130px,1fr));gap:12px;padding:17px;background:#f4f4ed;border:1px solid #d9ddcf;align-items:end}
.ud-filters label{display:flex;flex-direction:column;gap:7px;color:#284735;font:700 12px/1.4 system-ui,sans-serif;min-width:0}
.ud-filters select,.ud-filters input{min-width:0;width:100%;height:48px;color:#203f2c;border:1px solid #9bafa1;border-radius:4px;background:white;padding:11px 9px;font:500 13px system-ui,sans-serif}
.ud-filters>button{min-height:48px;border-radius:4px;border:1px solid #335841;color:#28543b;background:#fff;font-weight:700;cursor:pointer}
.ud-filters :is(select,input,button):focus-visible,.ud-card a:focus-visible,.ud-select:focus-visible,.ud-compare button:focus-visible{outline:3px solid #b78b46;outline-offset:3px}
.ud-count{color:#445b4a;font:700 13px system-ui,sans-serif;margin:20px 0}
.ud-grid{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:16px}
.ud-card{min-width:0;background:#fffefa;border:1px solid #dbddcf;display:flex;flex-direction:column;box-shadow:0 8px 27px #203c2b0e;border-radius:5px;overflow:hidden}
.ud-card[hidden]{display:none!important}
.ud-photo{display:grid;place-items:center;height:245px;min-width:0;background:radial-gradient(ellipse at 48% 40%,#fff,#ebeee7);padding:13px}
.ud-photo img{max-height:100%;max-width:100%;width:100%;height:100%;object-fit:contain}
.ud-art-fallback{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:9px;color:#e5e6da;text-align:center;width:100%;height:100%;padding:14px;background:radial-gradient(ellipse at 40% 20%,#517364,#263f39)}
.ud-art-fallback>span{font:700 12px system-ui;letter-spacing:.16em;text-transform:uppercase}
.ud-art-fallback strong{font:400 32px Georgia,serif;color:#fff}
.ud-art-fallback small{font:400 11px/1.6 system-ui,sans-serif}
.ud-card-main{display:flex;flex-direction:column;flex:1;padding:18px;gap:11px}
.ud-kicker{color:#88623d;letter-spacing:.06em;font:700 11px/1.5 system-ui,sans-serif;text-transform:uppercase;margin:0}
.ud-merchant-kind{align-self:flex-start;margin:0;padding:5px 8px;border:1px solid #c9d8c7;border-radius:3px;background:#eef5ed;color:#26513a;font:700 10px/1.35 system-ui,sans-serif}
.ud-card[data-merchant="search"] .ud-merchant-kind{border-color:#dbcba8;background:#faf3e7;color:#725127}
.ud-card[data-merchant="official"] .ud-merchant-kind{border-color:#d6d9d5;background:#f0f1ef;color:#4b5c50}
.ud-card h2{font:400 clamp(21px,2.2vw,29px)/1.17 Georgia,serif;margin:0;color:#20432e}
.ud-card h2 a{color:inherit;text-decoration:none}
.ud-card h2 a:hover{text-decoration:underline}
.ud-description{font:400 13px/1.68 system-ui,sans-serif;color:#4b6051;margin:0;flex:1}
.ud-card dl{display:grid;grid-template-columns:1fr 1fr;gap:12px;margin:0}
.ud-card dl>div{min-width:0;border-top:1px solid #dedfd5;padding-top:9px}
.ud-card dt{color:#647767;font:650 11px system-ui,sans-serif}
.ud-card dd{color:#264633;margin:4px 0;font:600 12px/1.4 system-ui,sans-serif;overflow-wrap:anywhere}
.ud-actions{display:grid;gap:8px;margin-top:auto}
.ud-actions a,.ud-select{display:grid;place-items:center;text-align:center;min-height:44px;border-radius:4px;padding:10px 12px;text-decoration:none;font:700 12px/1.35 system-ui,sans-serif;cursor:pointer}
.ud-details{background:#2c543d;color:#fff!important}
.ud-merchant{border:1px solid #a9bcad;background:#f0f5ed;color:#235138!important}
.ud-select{width:100%;border:1px solid #c4cbbf;background:#fffdf7;color:#294934}
.ud-select[aria-pressed=true]{border-color:#306045;background:#e2eee6}
.ud-compare{margin:60px 0 30px;padding:25px;background:#f6f4ed;border-top:3px solid #4d7559;color:#2a4935}
.ud-compare h2{font:400 clamp(29px,4vw,43px)/1.2 Georgia,serif;margin:0 0 14px}
.ud-compare p{font:400 14px/1.7 system-ui,sans-serif}
.ud-compare #udCompareClear{min-height:44px;background:#fff;border:1px solid #30583c;color:#2c553d;border-radius:4px;padding:9px 16px;cursor:pointer;font-weight:700}
#udCompareTable{overflow-x:auto;margin-top:15px}
.ud-matrix{width:100%;min-width:540px;border-collapse:collapse;background:#fff}
.ud-matrix caption{text-align:left;padding:12px;color:#405e4b;font-weight:700}
.ud-matrix th,.ud-matrix td{border:1px solid #cbd8cd;padding:12px 13px;text-align:left;font:500 13px/1.5 system-ui,sans-serif;vertical-align:top}
.ud-matrix th{font-weight:750;background:#eff3ed}
.ud-matrix th a{display:block;color:#23533a;text-decoration:underline}
.ud-compare-remove{border:0;background:transparent;padding:8px 0;color:#72532d;text-decoration:underline;cursor:pointer}
.ud-back{color:#395541;font:700 14px/1.9 system-ui,sans-serif}
.ud-back a{color:#225b3b}
@media(max-width:1220px){.ud-filters{grid-template-columns:repeat(3,minmax(0,1fr))}.ud-grid{grid-template-columns:repeat(3,minmax(0,1fr))}}
@media(max-width:850px){.ud-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.ud-photo{height:235px}}
@media(max-width:580px){.ud-page{padding-top:20px}.ud-filters{grid-template-columns:repeat(2,minmax(0,1fr));gap:10px;padding:12px}.ud-filters label:first-child{grid-column:1/-1}.ud-grid{gap:10px}.ud-photo{height:185px;padding:6px}.ud-card-main{padding:12px;gap:8px}.ud-card h2{font-size:19px}.ud-card dl{grid-template-columns:1fr}.ud-card dl>div:last-child{display:none}.ud-description{font-size:12px}.ud-actions a,.ud-select{font-size:11px;padding:8px 7px}.ud-compare{padding:15px}.ud-heading h1{font-size:42px}}
@media(max-width:365px){.ud-grid{grid-template-columns:1fr}.ud-photo{height:250px}.ud-filters{grid-template-columns:1fr}.ud-filters label:first-child{grid-column:auto}}
@media(prefers-reduced-motion:reduce){.ud-card,.ud-card *, .ud-filters *{animation:none!important;transition:none!important}}

/* Watch-to-watch comparison is visible immediately on mobile, even with long
   52-item result sets. HTML remains hidden without successful enhancement. */
.ud-tray[hidden],.ud-tray-open[hidden]{display:none!important}
.ud-tray{position:fixed;z-index:80;bottom:max(12px,env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);width:calc(100% - 24px);max-width:1010px;display:flex;align-items:center;gap:15px;padding:12px 16px;border-radius:12px;border:1px solid #a9c3b0;background:#1d3b2b;color:#fff;box-shadow:0 14px 42px #12241bb3;font-family:system-ui,sans-serif}
.ud-has-tray{padding-bottom:190px}
.ud-tray-heading{display:flex;flex-direction:column;gap:4px;flex:0 0 auto;min-width:115px}
.ud-tray-heading strong{font-size:13px;line-height:1.3;color:#fff}
.ud-tray-heading span{color:#d1e7d7;font-size:11px;line-height:1.45}
.ud-tray-items{display:flex;align-items:center;gap:8px;margin:0;padding:3px 0;list-style:none;flex:1 1 auto;min-width:0;overflow-x:auto;overscroll-behavior-x:contain}
.ud-tray-item{flex:0 0 auto;display:flex;align-items:center;gap:2px;border:1px solid #9fbfa8;background:#f3f6ee;border-radius:7px;color:#264431;max-width:235px}
.ud-tray-name{min-width:0;max-width:182px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;padding:9px 2px 9px 12px;font-size:12px;font-weight:700}
.ud-tray-remove{display:grid;place-items:center;flex:0 0 44px;min-height:44px;border:0;background:transparent;border-radius:7px;color:#264431;font-size:23px;cursor:pointer}
.ud-tray-actions{display:flex;align-items:center;gap:9px;flex:0 0 auto}
.ud-tray-open,.ud-tray-actions button{display:grid;place-items:center;min-height:46px;padding:10px 15px;text-align:center;border-radius:6px;font-size:12px;line-height:1.3;font-weight:750;white-space:nowrap}
.ud-tray-open{background:#e3ca88;color:#193727;text-decoration:none}
.ud-tray-actions button{border:1px solid #b0ccb8;background:transparent;color:#f4fff7;cursor:pointer}
.ud-tray :is(a,button):focus-visible{outline:3px solid #ffe08f;outline-offset:3px}
.ud-tray :is(a,button):hover{filter:brightness(1.12)}
@media(max-width:700px){
  .ud-tray{display:grid;grid-template-columns:minmax(0,1fr) auto;grid-template-areas:"heading actions" "items items";column-gap:8px;row-gap:7px;padding:10px 12px 11px;border-radius:10px;bottom:max(8px,env(safe-area-inset-bottom))}
  .ud-tray-heading{grid-area:heading;min-width:0}
  .ud-tray-items{grid-area:items;max-width:100%;padding-top:2px}
  .ud-tray-actions{grid-area:actions}
  .ud-tray-open,.ud-tray-actions button{min-height:44px;padding:9px 10px;font-size:11px}
  .ud-tray-name{max-width:170px}
  .ud-has-tray{padding-bottom:230px}
}
@media(max-width:365px){
  .ud-tray-open{white-space:normal}
  .ud-tray-name{max-width:125px}
  .ud-tray-actions{gap:4px}
  .ud-tray-actions button,.ud-tray-open{padding:8px}
}

/* Editorial showroom: one model photograph per verified local asset; all other
   listings remain clearly marked as without a published photograph. */
.ud-media{position:relative;min-width:0;isolation:isolate;overflow:hidden;background:#f1f1ea}
.ud-media-verified .ud-photo{background:radial-gradient(ellipse at 47% 39%,#fffefa 2%,#e9ede6 85%);padding:18px}
.ud-media-verified .ud-photo img{object-fit:contain;filter:drop-shadow(0 16px 14px #23372820);transition:transform .28s ease,filter .28s ease}
.ud-visual-label{position:absolute;z-index:2;top:10px;left:10px;max-width:calc(100% - 20px);padding:7px 10px;background:#fdfbf0ed;color:#274731;border:1px solid #d7d6c8;border-radius:3px;font:700 10px/1.35 system-ui,sans-serif;letter-spacing:.02em;pointer-events:none}
.ud-media-no-photo .ud-visual-label{color:#fff;background:#263f35ef;border-color:#759481}
.ud-art-fallback{position:relative;gap:7px;padding:44px 15px 16px;background:radial-gradient(circle at 50% 32%,#627c6d 0%,#2e4c3e 64%,#1c3028 100%)}
.ud-art-fallback:before{content:"";position:absolute;inset:18% 16%;border:1px solid #d7dfc928;border-radius:50%;pointer-events:none}
.ud-art-fallback .ud-art-fallback-kicker{font:700 10px/1.4 system-ui,sans-serif;letter-spacing:.05em;color:#e5e9df}
